import sys

s = sys.stdin.read()

# First pass: flip case for letters
first_pass = []
for ch in s:
    if ch.isalpha():
        first_pass.append(ch.swapcase())
    else:
        first_pass.append(ch)
first_pass = ''.join(first_pass)

# Second pass: for vowels, add 2 to ASCII
vowels = set('aeiouAEIOU')
result = []
for ch in first_pass:
    if ch in vowels:
        result.append(chr(ord(ch) + 2))
    else:
        result.append(ch)

sys.stdout.write(''.join(result))

