import sys

text = sys.stdin.read()
tokens = text.split()
depths = []
for t in tokens:
    depth = 0
    max_depth = 0
    for ch in t:
        if ch == '(':
            depth += 1
            if depth > max_depth:
                max_depth = depth
        elif ch == ')':
            if depth > 0:
                depth -= 1
    depths.append(max_depth)

print(depths)
